    info_forward_secrecy_title: "फ़ॉरवर्ड सीक्रेसी क्या है?",
    info_forward_secrecy_description:
      "आपकी सत्र कुंजियां तय समय पर अपने आप बदलती रहती हैं। अगर किसी को आज आपकी निजी कुंजी मिल भी जाए, तो वह पुराने संदेश नहीं पढ़ सकता, क्योंकि हर सत्र ने अलग कुंजी इस्तेमाल की थी जो अब मौजूद नहीं है।",
    info_key_rotation_interval_title: "कुंजी बदलने का अंतराल",
    info_key_rotation_interval_description:
      "आपकी एन्क्रिप्शन कुंजी कितनी बार बदली जाती है। जितनी बार ज़्यादा, उतनी सुरक्षा ज़्यादा, पर थोड़ा बोझ भी बढ़ता है। ज़्यादातर लोगों के लिए एक हफ़्ता अच्छा डिफ़ॉल्ट है।",
    info_key_history_limit_title: "कुंजी इतिहास सीमा",
    info_key_history_limit_description:
      "Aster कितनी पुरानी कुंजियां रखता है ताकि आप पुरानी ईमेल अब भी खोल सकें। इसे बहुत कम रखने पर पिछली बदली से पहले के संदेश पढ़े नहीं जा सकेंगे।",
    info_wkd_title: "WKD क्या है?",
    info_wkd_description:
      "एक मानक जिससे Thunderbird या Proton जैसे ईमेल ऐप आपकी सार्वजनिक कुंजी अपने आप खोज लेते हैं। लोग आपको एन्क्रिप्टेड मेल भेज सकते हैं और आपको अपनी कुंजी खुद साझा नहीं करनी पड़ती।",
    info_keyservers_title: "कीसर्वर क्या हैं?",
    info_keyservers_description:
      "सार्वजनिक डायरेक्टरी जहां PGP कुंजियां ईमेल से खोजी जा सकती हैं। यहां प्रकाशित करने पर कोई भी आपकी कुंजी पा सकता है। ध्यान रखें: ज़्यादातर कीसर्वर एक बार प्रकाशित कुंजी को पूरी तरह हटाने नहीं देते।",
    keyserver_urls_title: "कीसर्वर URL",
