    keyserver_invalid_url: "मान्य HTTPS URL डालें",
    keyserver_saved: "कीसर्वर सूची सहेज ली गई",
    keyserver_publication_status: "प्रकाशन स्थिति",
    keyserver_status_published: "प्रकाशित",
    keyserver_status_not_published: "प्रकाशित नहीं",
