    verification_help:
      'ज़्यादातर रजिस्ट्रार के पास DNS या Zone Editor वाला हिस्सा होता है। "Add Record" या "Manage DNS" जैसे विकल्प देखें। रिकॉर्ड के प्रकार में TXT चुनें।',
    mx_help:
      "MX रिकॉर्ड दूसरे मेल सर्वरों को बताते हैं कि आपके डोमेन की ईमेल कहां पहुंचानी है। प्राथमिकता संख्या तय करती है कि सर्वर किस क्रम में आज़माए जाएं (कम = पहले)।",
    spf_help:
      "SPF रिकॉर्ड TXT रिकॉर्ड होते हैं जो बताते हैं कि आपके डोमेन के लिए कौन से मेल सर्वर ईमेल भेज सकते हैं। हर डोमेन पर सिर्फ़ एक SPF रिकॉर्ड होना चाहिए।",
    dkim_help:
      "DKIM, Ed25519 क्रिप्टोग्राफ़िक हस्ताक्षर इस्तेमाल करता है। Aster से भेजा गया हर ईमेल एक निजी कुंजी से हस्ताक्षरित होगा, और पाने वाले सर्वर आपके DNS में मौजूद इस सार्वजनिक कुंजी से हस्ताक्षर की पुष्टि करते हैं।",
