    info_low_network_mode_description:
      "धीमे या सीमित डेटा वाले कनेक्शन पर Aster चलता रहे, इसके लिए सभी गैर-ज़रूरी नेटवर्क अनुरोध रोक देता है। प्रोफ़ाइल तस्वीरें, प्रेषक के लोगो, डोमेन फ़ेविकॉन, ईमेल में बाहरी तस्वीरें, ईमेल पहले से लोड करना, कस्टम फ़ॉन्ट, अटैचमेंट झलक और सूचना ध्वनियां बंद कर देता है। सारी ईमेल सादे टेक्स्ट में दिखती हैं। बातचीत में ज़्यादा से ज़्यादा 4 संदेश दिखते हैं। 2G या Save-Data कनेक्शन पर यह अपने आप चालू हो जाता है। आप इसे URL में ?low_bandwidth=1 लगाकर भी चालू कर सकते हैं।",
