    health_check_failed:
      "जांच पूरी नहीं हुई। एक और कोशिश से काम बन जाना चाहिए।",
    unexpected_health_check_error:
      "जांच में अड़चन आ गई। एक और कोशिश से काम बन जाना चाहिए।",
    all_emails_rejected:
      "इस फ़ाइल के सभी {{count}} ईमेल छोड़ दिए गए, क्योंकि हर एक में प्रेषक या मुख्य भाग नहीं था, और कुछ भी इंपोर्ट नहीं हुआ। स्रोत एक्सपोर्ट को दोबारा देखने से आमतौर पर बात बन जाती है।",
    wrong_vault_password:
      "उस पासवर्ड से इस डिवाइस पर आपकी कुंजियां अनलॉक नहीं हुईं। एक और कोशिश से काम बन जाना चाहिए, और अगर बार-बार नाकाम रहे तो astermail.org/reset पर रिकवरी कोड बैकअप है। सर्वर पर आपका डेटा वैसा का वैसा है।",
    vault_tampered:
      "इस डिवाइस का एन्क्रिप्टेड डेटा उससे मेल नहीं खाता जिसकी हमें उम्मीद थी, जो छेड़छाड़ का संकेत हो सकता है। जांचने के लिए सेटिंग और फिर सुरक्षा में जाएं, और अगर चेतावनी फिर आए तो hello@astermail.org से संपर्क करें। सर्वर पर आपके डेटा पर कोई असर नहीं पड़ा है।",
    vault_version_drift:
      "आपका एन्क्रिप्टेड स्टोरेज Aster के किसी पुराने संस्करण का है, इसलिए हम इसे अभी अपग्रेड कर रहे हैं। आपका डेटा सुरक्षित है और यह सिर्फ़ एक बार होता है।",
    vault_missing_key:
      "यह स्टोरेज पढ़ने के लिए ज़रूरी डिवाइस कुंजी हमें नहीं मिली। साइन आउट करके फिर से साइन इन करने पर यह डिवाइस दोबारा जुड़ जाएगा। सर्वर पर आपके डेटा पर कोई असर नहीं पड़ा है।",
    wrong_folder_password:
      "फ़ोल्डर का पासवर्ड गलत है। फिर से कोशिश करें। फ़ोल्डर लॉक ही रहेगा।",
    wrong_external_account_password:
      "उस बाहरी खाते का पासवर्ड मेल नहीं खाया। सेटिंग में इसे जांचकर एक और कोशिश करने से आमतौर पर काम बन जाता है। आपका सहेजा गया कनेक्शन जस का तस है।",
    decrypt_wrong_key:
      "इस डिवाइस पर यह ईमेल पढ़ने के लिए हमारे पास सही कुंजी नहीं है। साइन आउट करके फिर से साइन इन करने से आमतौर पर काम बन जाता है। आपका ईमेल सर्वर पर सुरक्षित है।",
    decrypt_corrupt_ciphertext:
      "यह ईमेल सर्वर पर मौजूद है, लेकिन रास्ते में खराब लगता है। रीफ़्रेश करके एक और कोशिश आमतौर पर काम कर जाती है, और बार-बार विफल होने पर hello@astermail.org मदद कर सकता है।",
    decrypt_sender_error:
      "प्रेषक ने यह ईमेल ऐसे तरीके से एन्क्रिप्ट किया है जिसे हम पढ़ नहीं सकते। उनसे इसे दोबारा भेजने को कहने से काम बन जाना चाहिए। आपके बाकी ईमेल पर कोई असर नहीं पड़ा है।",
    metadata_undecryptable_change:
      "यह डिवाइस इस संदेश का विवरण नहीं खोल सकता, इसलिए आपका बदलाव सहेजा नहीं गया। अपनी कुंजियां दोबारा लोड करने के लिए, साइन आउट करके फिर से साइन इन करें। सर्वर पर आपका संदेश जस का तस है।",
