    cdn_relay_misconfigured:
      "इस बिल्ड के लिए CDN रिले सेट नहीं है। सेटिंग में सीधे कनेक्शन पर जाने से आप दोबारा ऑनलाइन हो जाएंगे, और ज़रूरत पड़ने पर hello@astermail.org मदद कर सकता है।",
    device_repair_required:
      "इस डिवाइस की कुंजी मौजूद नहीं है। अपने डेस्कटॉप ऐप से दोबारा जोड़ने पर बात बन जाएगी। आपका खाता और डेटा जस के तस हैं।",
    device_challenge_mismatch:
      "इस डिवाइस की पहचान जांच मेल नहीं खाई, जो छेड़छाड़ का संकेत हो सकता है। अपने डेस्कटॉप ऐप से दोबारा जोड़ें, और अगर चेतावनी फिर आए तो hello@astermail.org से संपर्क करें।",
